// `useHello` is generated by orval from the backend module's OpenAPI schema
// (run `pnpm run build:modules`, which regenerates `src/api/ocelEditor.ts`).
import { useHello } from "../api/ocelEditor";

export default function Hello() {
  const { data, isPending, isError } = useHello();

  return (
    <div>
      <h1>Ocel Editor</h1>
      <p>
        {isPending
          ? "Loading…"
          : isError
            ? "Could not reach the backend module."
            : data?.message}
      </p>
      <p>
        Edit this frontend module and the <code>ocelEditor</code> backend
        module to build your own module.
      </p>
    </div>
  );
}
